@router.put("/settings", response_model=SettingsResponse)
async def update_settings(request: SettingsUpdate):
    """
    Update application settings.

    Legacy endpoint — kept for backward compatibility.
    Delegates to the new provider registry for actual persistence.
    Prefer PATCH /settings for new code.
    """
    from local.llm.provider_registry import get_provider_registry
    reg = get_provider_registry()
    updated = {}
    if request.ollama_model:
        reg.set_local_model(request.ollama_model)
        updated["ollama_model"] = request.ollama_model
    if request.top_k is not None:
        updated["top_k"] = request.top_k

    return SettingsResponse(status="updated", settings=updated)
